fn dbl(x: i64) -> i64 { x * 2 } fn add(a: i64, b: i64) -> i64 { a + b } fn ap(f: fn(i64) -> i64, v: i64) -> i64 { f(v) } struct S { f: fn(i64) -> i64 } fn main() { let g = dbl; let s = S { f: dbl }; let dbl2 = 5; let v: Vec<i64> = vec![1, 2, 3].into_iter().map(dbl).collect(); println!("{} {} {} {} {:?} {}", ap(dbl, 4), g(10), (s.f)(7), dbl2, v, [1, 2].iter().fold(0, |a, b| add(a, *b))); }
